export const useRegisterPushToken = <TError = ErrorType<BadRequestResponse | UnauthorizedResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof registerPushToken>>, TError,{data: BodyType<PushTokenInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof registerPushToken>>,
        TError,
        {data: BodyType<PushTokenInput>},
        TContext
      > => {
      return useMutation(getRegisterPushTokenMutationOptions(options));
    }

export const getUnregisterPushTokenUrl = () => {




  return `/api/push/register`
}

/**
 * @summary Remove a push token
 */
export const unregisterPushToken = async (pushTokenDelete: PushTokenDelete, options?: Parameters<typeof customFetch>[1]): Promise<void> => {

  return customFetch<void>(getUnregisterPushTokenUrl(),
  {
    ...options,
    method: 'DELETE',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(pushTokenDelete)
  }
);}





export const getUnregisterPushTokenMutationOptions = <TError = ErrorType<BadRequestResponse | UnauthorizedResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof unregisterPushToken>>, TError,{data: BodyType<PushTokenDelete>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof unregisterPushToken>>, TError,{data: BodyType<PushTokenDelete>}, TContext> => {

const mutationKey = ['unregisterPushToken'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof unregisterPushToken>>, {data: BodyType<PushTokenDelete>}> = (props) => {
          const {data} = props ?? {};

          return  unregisterPushToken(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type UnregisterPushTokenMutationResult = NonNullable<Awaited<ReturnType<typeof unregisterPushToken>>>
    export type UnregisterPushTokenMutationBody = BodyType<PushTokenDelete>
    export type UnregisterPushTokenMutationError = ErrorType<BadRequestResponse | UnauthorizedResponse>

    /**
 * @summary Remove a push token
 */
export const useUnregisterPushToken = <TError = ErrorType<BadRequestResponse | UnauthorizedResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof unregisterPushToken>>, TError,{data: BodyType<PushTokenDelete>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof unregisterPushToken>>,
        TError,
        {data: BodyType<PushTokenDelete>},
        TContext
      > => {
      return useMutation(getUnregisterPushTokenMutationOptions(options));
    }

